export function creationHTML({classes,selected,name,artStyle,escape,saved,legacy}){
 const c=classes[selected];
 return `<div class="creation-intro">Один герой. Сім шляхів. Оберіть свій клас.</div><div class="class-grid">${Object.entries(classes).map(([id,c])=>`<button class="class-card ${id===selected?'selected':''}" data-class="${id}" aria-pressed="${id===selected}"><span class="preview-art" style="${artStyle(id)}"></span><b>${c.name}</b><small>${c.role}</small></button>`).join('')}</div><div class="creation-summary"><div class="creation-description"><b>${c.name}</b><p>${c.skills.map(s=>s.icon+' '+s.name).join(' · ')}</p><small>Спеціалізації: 20 / 40 / 60 · фінальна форма: 85</small></div><label class="creation-name" for="character-name">Ім’я персонажа<input id="character-name" maxlength="22" value="${escape(name||'Мандрівник')}" aria-label="Ім’я персонажа"></label></div>${legacy&&!saved?'<label class="checkline"><input id="migrate-legacy" type="checkbox" checked> Перенести попереднього героя</label>':''}<nav class="creation-actions" aria-label="Початок пригоди"><button id="start-local" class="btn">Почати локальну пригоду →</button>${saved?'<button id="continue-local" class="btn secondary">Продовжити збережену гру</button>':''}<button id="start-coop-menu" class="btn secondary">Кооператив · до 8 гравців</button></nav><p class="creation-footnote">Прогрес зберігається на пристрої. У кооперативі кожен керує власним героєм.</p>`;
}
